package com.nextrade.api.security; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.web.*; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; @Configuration @EnableWebSecurity @EnableMethodSecurity public class SecurityConfig { @Bean public AccessTokenService accessTokenService(com.nextrade.service.JwtKeyRing ring){return new AccessTokenService(ring,java.time.Duration.ofMinutes(15));} @Bean public JwtAuthenticationFilter jwtAuthenticationFilter(AccessTokenService s){return new JwtAuthenticationFilter(s);} @Bean public SecurityFilterChain security(HttpSecurity http,JwtAuthenticationFilter filter)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/register","/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/auth/forgot-password","/api/v1/auth/verify-reset-token","/api/v1/auth/reset-password","/api/v1/auth/verify-email","/api/v1/auth/resend-verification","/api/v1/market/**","/actuator/health","/ws/**").permitAll().requestMatchers("/api/v1/auth/logout","/api/v1/auth/logout-all","/api/v1/auth/change-password").authenticated().requestMatchers("/api/v1/admin/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}}